'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

(async () => {
  // Newer flight is not detached by obsolete flight settling; dedup intact.
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b1 = c.get('k'); await tick();
    gates[0].resolve('old'); assert.equal(await a, 'old');
    const b2 = c.get('k'); await tick();
    assert.equal(calls, 2, 'b2 must join flight 2');
    gates[1].resolve('new');
    assert.equal(await b1, 'new'); assert.equal(await b2, 'new');
    assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
  }
  // Rejection not cached; retry allowed; shared reason; non-Error and sync throw.
  {
    let calls = 0; const reason = { r: 1 };
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw reason; return 'ok'; } });
    const p1 = c.get('k'), p2 = c.get('k');
    await assert.rejects(p1, x => x === reason); await assert.rejects(p2, x => x === reason);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 2);
  }
  // Obsolete rejection does not detach newer flight.
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k'); const b = c.get('k'); await tick();
    gates[0].reject(new Error('x')); await assert.rejects(a);
    const b2 = c.get('k'); await tick(); assert.equal(calls, 2);
    gates[1].resolve('v'); assert.equal(await b, 'v'); assert.equal(await b2, 'v');
  }
  // set wins, old load cannot restart TTL; expiry starts new load.
  {
    let t = 0; const g = deferred(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (calls++ === 0 ? g.promise : 'fresh') });
    const a = c.get('k'); await tick();
    c.set('k', 'manual'); t = 5; g.resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'manual');
    t = 10; assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'fresh'); assert.equal(calls, 2);
  }
  // clear detaches; load calling invalidate synchronously makes its own flight obsolete.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load: k => { calls++; if (calls === 1) c.invalidate(k); return 'v' + calls; } });
    assert.equal(await c.get('k'), 'v1'); assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v2'); assert.equal(c.size, 1);
    c.clear(); assert.equal(c.size, 0);
  }
  // load reads own key without awaiting -> joins flight.
  {
    let calls = 0, inner;
    const c = createCache({ now: () => 0, load: k => { calls++; inner = c.get(k); return 'v'; } });
    assert.equal(await c.get('k'), 'v'); assert.equal(await inner, 'v'); assert.equal(calls, 1);
  }
  // ttlMs 0 dedups but does not reuse.
  {
    let calls = 0; const g = deferred();
    const c = createCache({ now: () => 0, ttlMs: 0, load: () => { calls++; return g.promise; } });
    const a = c.get('k'), b = c.get('k'); await tick(); g.resolve(1);
    await a; await b; assert.equal(calls, 1);
    await c.get('k'); assert.equal(calls, 2); assert.equal(c.size, 0);
  }
  console.log('ALL OK');
})().catch(e => { console.error(e); process.exit(1); });

